import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r'''
.version 7.8
.target sm_89
.address_size 64
.visible .entry tanh_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 n
)
{
    .reg .pred %p<6>;
    .reg .b32 %r<24>;
    .reg .b64 %rd<16>;
    .reg .f32 %f<16>;
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r6, [n];
    shr.u32 %r7, %r6, 2;
    and.b32 %r8, %r6, 3;
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mad.lo.u32 %r4, %r1, %r2, %r3;
    mov.u32 %r11, %r4;
    mov.u32 %r5, %nctaid.x;
    mul.lo.u32 %r10, %r5, %r2;
VEC_LOOP:
    setp.ge.u32 %p1, %r4, %r7;
    @%p1 bra TAIL;
    mul.wide.u32 %rd3, %r4, 16;
    add.s64 %rd4, %rd1, %rd3;
    add.s64 %rd5, %rd2, %rd3;
    ld.global.v4.f32 {%f1, %f2, %f3, %f4}, [%rd4];
    tanh.approx.f32 %f5, %f1;
    tanh.approx.f32 %f6, %f2;
    tanh.approx.f32 %f7, %f3;
    tanh.approx.f32 %f8, %f4;
    st.global.v4.f32 [%rd5], {%f5, %f6, %f7, %f8};
    add.u32 %r4, %r4, %r10;
    bra VEC_LOOP;
TAIL:
    shl.b32 %r9, %r7, 2;
    setp.ge.u32 %p2, %r11, %r8;
    @%p2 bra DONE;
    add.u32 %r12, %r9, %r11;
    mul.wide.u32 %rd6, %r12, 4;
    add.s64 %rd7, %rd1, %rd6;
    add.s64 %rd8, %rd2, %rd6;
    ld.global.f32 %f9, [%rd7];
    tanh.approx.f32 %f10, %f9;
    st.global.f32 [%rd8], %f10;
DONE:
    ret;
}
'''
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("tanh_kernel")
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        out = torch.empty(x.shape, dtype=x.dtype, device=x.device)
        n = x.numel()
        if n == 0:
            return out
        module = _get_ptx_module()
        block_x = 256
        vec_n = n // 4
        tail = n - vec_n * 4
        work_items = vec_n if vec_n > 0 else tail
        grid_x = min(work_items, 32768)
        module.launch(
            "tanh_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, u32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
